31	// What a session may claim, and what each one means for the item. `record` is the
32	// execution-record status, and `null` means no record: an approval park is a run
33	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
34	// a fifth status would be stored data every decoder in the fleet must learn.
35	export const OUTCOMES = Object.freeze({
36	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
37	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
38	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
39	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
