52	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
53	  }
54	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
55	  if (args.outcome === 'approval' && !args.pr) {
56	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
57	  }
58	  return { issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null };
